"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type TiltClusterCard = {
  id: string;
  title: string;
  subtitle?: string;
  accent?: string;
};

export type TiltClusterProps = {
  cards: TiltClusterCard[];
  className?: string;
};

/**
 * Perspective tilt cluster — the whole stage leans toward the pointer while
 * each card keeps a subtle depth offset.
 */
function TiltCluster({ cards, className }: TiltClusterProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [tilt, setTilt] = React.useState({ rx: 0, ry: 0 });

  const onMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const el = ref.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    const px = (e.clientX - r.left) / r.width - 0.5;
    const py = (e.clientY - r.top) / r.height - 0.5;
    setTilt({ rx: py * -10, ry: px * 14 });
  };

  return (
    <div
      ref={ref}
      onMouseMove={onMove}
      onMouseLeave={() => setTilt({ rx: 0, ry: 0 })}
      className={cn("perspective-[1200px]", className)}
    >
      <div
        className="relative mx-auto grid h-[220px] w-full max-w-md place-items-center transition-transform duration-200 ease-out"
        style={{
          transform: `rotateX(${tilt.rx}deg) rotateY(${tilt.ry}deg)`,
          transformStyle: "preserve-3d",
        }}
      >
        {cards.slice(0, 3).map((card, i) => (
          <div
            key={card.id}
            className="absolute w-[70%] rounded-2xl border border-border bg-card p-4 shadow-[var(--shadow-lift)]"
            style={{
              transform: `translateZ(${40 - i * 28}px) translateY(${i * 18}px) translateX(${(i - 1) * 18}px)`,
              backgroundImage: card.accent
                ? `linear-gradient(160deg, color-mix(in oklch, ${card.accent} 18%, var(--color-card)), var(--color-card))`
                : undefined,
            }}
          >
            <div className="text-sm font-semibold tracking-tight">{card.title}</div>
            {card.subtitle ? (
              <div className="mt-1 text-xs text-muted-foreground">
                {card.subtitle}
              </div>
            ) : null}
          </div>
        ))}
      </div>
    </div>
  );
}

export { TiltCluster };
